// quality.js
(() => {
/**
 * Quality: a pile of seven identical postcards, a little uneven as a real pile
 * is, the top one showing its picture, its address and a check. Bring the
 * pointer near and the pile fans out into a staircase, on one spring, and the
 * same check shows on every card: scale did not break it. The slider is how
 * far apart each card can fan.
 */
const {
  Cam, fit, proj, facing, unproj, rrect, run, hull, poly, open, seg, fillet,
  clamp, rad, spring, stepS, mk, solid, put, register, pointer, disposer,
} = HL;

const N = 7, W = 74, D = 50, T = 1.6, GAP = 3.4, CX = W / 2, CY = D / 2;
// the pile's unevenness at rest: each card's nudge (x, y) and turn, in degrees
const NUDGE = [[0, 0, 0], [2, -1.5, 2.2], [-1.5, 1, -1.4], [1.5, 1.5, 1.6], [-1, -1, -2], [2, 0.5, 1], [0, 0, -0.8]];
// a check, drawn upright on screen: a along screen x, b along screen y
const TICK = fillet([[-5.2, 0.4], [-3.6, -1.2], [-1.2, 1.2], [4.4, -4.6], [6, -3], [-1.2, 4.4]], [0.8, 0.8, 0.5, 0.8, 0.8, 0.8], 3);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let MAX = value;
  const half = (N - 1) / 2;
  const C = Cam(45, 0.5, 2.12);
  fit(C, [[-half * 16, 0, 0], [W + half * 16, D, 0], [W + half * 16, 0, 0], [-half * 16, D, 0], [-half * 16, 0, N * GAP], [W, D, N * GAP]], 200, 164);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const outer = rrect(0, 0, W, D, 2.2, 4), inner = rrect(0.7, 0.7, W - 0.7, D - 0.7, 1.5, 4);

  const cards = NUDGE.map(([nx, ny, th], i) => {
    const s = solid(g);
    return {
      i, nx, ny, th, s,
      photo: mk("path", { class: "nf lo" }, s.g),
      lines: mk("path", { class: "nf lo" }, s.g),
      tick: mk("path", { class: i === N - 1 ? "nf hi" : "nf" }, s.g),
    };
  });

  /** Card i, offset by dx along x: the world point of its own (u, v) at height z. */
  const at = (c, dx) => {
    const a = rad(c.th), co = Math.cos(a), si = Math.sin(a);
    return (u, v, z) => {
      const x = u - CX, y = v - CY;
      return P(CX + c.nx + dx + x * co - y * si, CY + c.ny + x * si + y * co, z);
    };
  };
  const turnRing = (w, r, z) => r.map((q) => w(q.u, q.v, z));

  const spread = spring(0, { eps: 0.02 });
  let drawn = NaN;
  function draw() {
    const s = spread.x;
    if (s === drawn) return;
    drawn = s;
    for (const c of cards) {
      // the top of the pile moves back, the bottom forward: a staircase
      const w = at(c, (half - c.i) * s), z0 = c.i * GAP, z1 = z0 + T;
      const turned = (ring) => ring.map((q) => {
        const a = rad(c.th);
        return { ...q, nu: q.nu * Math.cos(a) - q.nv * Math.sin(a), nv: q.nu * Math.sin(a) + q.nv * Math.cos(a) };
      });
      put(c.s, {
        sil: poly(hull(turnRing(w, outer, z0).concat(turnRing(w, outer, z1)))),
        crease: open(run(turned(inner), front).map((q) => w(q.u, q.v, z1))),
      });
      const top = (pts) => poly(pts.map(([u, v]) => w(u, v, z1)));
      c.photo.setAttribute("d", top(rrect(6, 6, 30, D - 6, 2, 3).map((q) => [q.u, q.v])));
      c.lines.setAttribute("d", [[36, 12, 58], [36, 18, 52], [36, 24, 56]].map(([u0, v, u1]) => seg(w(u0, v, z1), w(u1, v, z1))).join(""));
      const tx = W - 8.5, ty = D - 13;
      c.tick.setAttribute("d", top(TICK.map(([a, b]) => [tx + (a + b) * 0.71, ty + (b - a) * 0.71])));
    }
  }
  draw();

  const B = register(stage, (dt) => { const m = stepS(spread, dt); draw(); return m; });
  bag.add(B.unregister);

  function aim(t) {
    spread.t = t;
    // a lower card's check shows once the card above has moved back past it
    read.textContent = t === 0 ? "rest" : `${t >= 12 ? N : 1} of ${N}`;
    B.wake();
  }
  bag.add(pointer(stage, {
    // nearness to the pile's middle, on the ground: the nearer, the wider the fan
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      const d = Math.hypot(x - CX, y - CY);
      aim(MAX * clamp(1 - (d - 28) / 60, 0, 1));
    },
    leave: () => aim(0),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { MAX = v; }, destroy: bag.dispose };
}

hairline({
  name: "quality",
  means: "A pile of identical postcards: bring the pointer near and it fans out, and the same check shows on every card.",
  rules: [3, 4, 5, 6],
  range: [12, 14, 16],
  mount,
});

})();
// scans.js
(() => {
/**
 * Scans: a board of fifteen bars, one per mail route, on a rounded plinth. At
 * rest they stand as a week of results, rising to the right, the tallest
 * bright. The pointer is projected onto the ground, and each bar takes its
 * height from its distance to it, on its own spring: the routes near it are
 * read out. The slider is the radius, in rows.
 */
const {
  Cam, fit, prism, proj, rings, unproj, spring, stepS, clamp, facing,
  mk, pointer, put, register, disposer, solid,
} = HL;

const NX = 5, NY = 3, CELL = 22, FOOT = 15, HMAX = 66, PB = 5;
const EX = NX * CELL, EY = NY * CELL;

const falloff = (u) => (u <= 0 ? 1 : u <= 0.45 ? 1 - (u / 0.45) * 0.6 : u <= 1 ? 0.4 - ((u - 0.45) / 0.55) * 0.28 : 0.12);

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  const C = Cam(45, 0.5, 2.1);
  fit(C, [[-8, -8, -PB], [EX + 8, EY + 8, -PB], [EX + 8, -8, -PB], [-8, EY + 8, -PB], [EX, 0, HMAX], [0, EY, HMAX]], 200, 170);
  const P = proj(C), front = facing(C);
  let R = value * CELL, over = null;

  const g = mk("g", {}, svg), bars = [];
  const [pr, pi] = rings(-8, -8, EX + 8, EY + 8, 10, 2.2);
  put(solid(g), prism(P, front, pr, pi, -PB, 0));
  // Back to front: by ascending i + j from the far corner.
  for (let s = 0; s <= NX + NY - 2; s++) for (let i = 0; i < NX; i++) {
    const j = s - i;
    if (j < 0 || j >= NY) continue;
    // rest: the results of a week, climbing to the right, a dip in the middle
    const h0 = 10 + i * 9 + (j === 1 ? 6 : 0) - (i === 2 ? 8 : 0);
    const x0 = i * CELL + (CELL - FOOT) / 2, y0 = j * CELL + (CELL - FOOT) / 2;
    const [ring, inner] = rings(x0, y0, x0 + FOOT, y0 + FOOT, 3.2, 1.1);
    bars.push({ i, j, h0, ring, inner, sp: spring(h0, { eps: 0.04 }), el: solid(g), drawn: NaN });
  }
  const top = bars.reduce((a, b) => (b.h0 > a.h0 ? b : a));
  let lit = top;

  function draw(b) {
    const h = Math.max(1, b.sp.x);
    if (h === b.drawn) return;
    b.drawn = h;
    put(b.el, prism(P, front, b.ring, b.inner, 0, h));
  }
  const B = register(stage, (dt) => {
    let m = false;
    for (const b of bars) { if (stepS(b.sp, dt)) m = true; draw(b); }
    return m;
  });
  bag.add(B.unregister);

  function light(b) {
    if (b === lit) return;
    lit.el.sil.classList.remove("hi");
    lit = b;
    lit.el.sil.classList.add("hi");
  }
  light(top); top.el.sil.classList.add("hi");

  function retarget() {
    for (const b of bars) {
      if (!over) { b.sp.t = b.h0; continue; }
      const dx = (b.i + 0.5) * CELL - over[0], dy = (b.j + 0.5) * CELL - over[1];
      b.sp.t = HMAX * falloff(Math.hypot(dx, dy) / R);
    }
    if (over) {
      const i = clamp(Math.floor(over[0] / CELL), 0, NX - 1), j = clamp(Math.floor(over[1] / CELL), 0, NY - 1);
      light(bars.find((b) => b.i === i && b.j === j));
      read.textContent = `route ${j * NX + i + 1}`;
    } else { light(top); read.textContent = "rest"; }
    B.wake();
  }

  bag.add(pointer(stage, {
    move: (p) => { over = unproj(C, p[0], p[1], 0); retarget(); },
    leave: () => { over = null; retarget(); },
  }));
  bag.add(() => svg.replaceChildren());
  return { set: (v) => { R = v * CELL; if (over) retarget(); }, destroy: bag.dispose };
}

hairline({
  name: "scans",
  means: "Fifteen routes as bars on a board: the routes near the pointer rise, so you read where the scans came from.",
  rules: [1, 3, 5, 9],
  range: [1, 1.8, 3],
  mount,
});

})();
export { HL, figures };
